code.text:
variable "name_prefix" {
  type = string # "ai-agents", from account.hcl
}

variable "sizes" {
  type        = map(string)
  description = "One launch template and one ASG per key; the value is the instance type."
}

variable "warm_pool_size" {
  type = map(number) # { lite = 2, full = 2, wide = 0 }
  validation {
    condition     = alltrue([for n in values(var.warm_pool_size) : n >= 0 && n <= 3])
    error_message = "A warm pool holds 0 to 3 VMs (the group's max_size is 3)."
  }
}

variable "subnet_ids" {
  type = list(string)
}

variable "tags" {
  type = map(string)
}

resource "aws_launch_template" "sandbox" {
  for_each = var.sizes # { lite = "m8i.xlarge", full = "m8i.2xlarge", wide = "m8i.4xlarge" }

  name          = "${var.name_prefix}-sandbox-${each.key}"
  image_id      = "resolve:ssm:/ai-agents/sandbox/ami-id" # promoted by the nightly smoke test (G3-16)
  instance_type = each.value

  iam_instance_profile { name = aws_iam_instance_profile.sandbox.name } # SSM core only
  vpc_security_group_ids = [aws_security_group.sandbox.id]              # no ingress at all
  metadata_options {
    http_endpoint               = "enabled"
    http_tokens                 = "required"
    http_put_response_hop_limit = 1 # containers on the docker bridge can't get a token
    instance_metadata_tags      = "disabled"
  }

  block_device_mappings {
    device_name = "/dev/sda1"
    ebs {
      volume_type                = "gp3"
      volume_size                = 120
      encrypted                  = true
      kms_key_id                 = aws_kms_key.sandbox.arn
      volume_initialization_rate = 300 # MiB/s; check aws provider 6.64.0 supports this argument
    }
  }

  dynamic "tag_specifications" {
    for_each = ["instance", "volume"]
    content {
      resource_type = tag_specifications.value
      tags          = merge(var.tags, { "ai-agents:managed" = "true", "ai-agents:size" = each.key })
    }
  }
}

resource "aws_autoscaling_group" "sandbox" {
  for_each = var.sizes

  name                = "${var.name_prefix}-sandbox-${each.key}"
  vpc_zone_identifier = var.subnet_ids
  min_size            = 0
  max_size            = 3 # only claims in flight live here; claimed VMs are detached
  desired_capacity    = 0
  launch_template {
    id      = aws_launch_template.sandbox[each.key].id
    version = "$Latest"
  }
  warm_pool {
    pool_state                  = "Stopped" # a stopped VM costs only its disk
    min_size                    = var.warm_pool_size[each.key]
    max_group_prepared_capacity = var.warm_pool_size[each.key]
    instance_reuse_policy { reuse_on_scale_in = false } # a used VM never goes back
  }
  initial_lifecycle_hook {
    name                 = "finish-setup"
    lifecycle_transition = "autoscaling:EC2_INSTANCE_LAUNCHING"
    heartbeat_timeout    = 1800
    default_result       = "ABANDON"
  }
}

  # inside resource "aws_autoscaling_group" "sandbox", after initial_lifecycle_hook:
  dynamic "tag" {
    for_each = merge(var.tags, { "ai-agents:managed" = "true", "ai-agents:size" = each.key })
    content {
      key                 = tag.key
      value               = tag.value
      propagate_at_launch = true
    }
  }

# outputs.tf
output "launch_template_ids" {
  value = { for size, lt in aws_launch_template.sandbox : size => lt.id }
}

output "asg_names" {
  value = { for size, g in aws_autoscaling_group.sandbox : size => g.name }
}

locals {
  proxy_subnets = [for i in range(2) : cidrsubnet(cidrsubnet(var.vpc_cidr, 2, 3), 10, i)] # two /28s
  squid_conf = templatefile("${path.module}/templates/squid.conf.tpl", {
    sandbox_cidrs = join(" ", var.sandbox_cidrs)
  })
}

resource "aws_subnet" "proxy" {
  count             = 2
  vpc_id            = var.vpc_id
  cidr_block        = local.proxy_subnets[count.index]
  availability_zone = var.azs[count.index]
  tags              = merge(var.tags, { Name = "${var.name_prefix}-proxy-${count.index}" })
}

resource "aws_internet_gateway" "this" { vpc_id = var.vpc_id }

resource "aws_route_table" "proxy" {
  vpc_id = var.vpc_id
  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.this.id # the only route out in the whole VPC
  }
}

terraform {
  required_providers {
    aws = { source = "hashicorp/aws", version = "6.64.0" } # the version common.hcl pins
  }
}

provider "aws" {
  region                      = "us-east-1"
  access_key                  = "test"
  secret_key                  = "test"
  skip_credentials_validation = true
  skip_requesting_account_id  = true
  skip_metadata_api_check     = true
  endpoints {
    autoscaling = "http://localhost:5055"
    ec2         = "http://localhost:5055"
    iam         = "http://localhost:5055"
    kms         = "http://localhost:5055"
    sts         = "http://localhost:5055"
  }
}
